--Thống kê doanh thu theo ngày, tháng, năm
CREATE PROC [dbo].[sp_ThongKeDoanhThu_DMY]
	(@Day INT,
	@Month INT,
	@Year INT)
AS
BEGIN
	SELECT
		HD.NGAYLAP,
		SUM(HD.THANHTIEN) TONGTIENHOMNAY
	FROM HOADON HD
	WHERE DAY(NGAYLAP) = @Day AND MONTH(NGAYLAP) = @Month AND YEAR(NGAYLAP) = @Year
	GROUP BY HD.NGAYLAP
END
GO
