--Thống kê doanh thu theo tháng cho biểu đồ cột
CREATE PROC [dbo].[sp_ThongKeDoanhThu_M_BarChart]
	(@Year INT)
AS
BEGIN
	SELECT
		MONTH(NGAYLAP) THANG,
		SUM(HD.THANHTIEN) TONGTIEN
	FROM HOADON HD
	WHERE YEAR(NGAYLAP) = @Year
	GROUP BY MONTH(NGAYLAP)
END
GO
